import re

PATTERN = re.compile(r'^(\S+) \S+ \S+ \[([^\]]+)\] "(\S+) (\S+) (\S+)" (\d{3}) (\d+|-) "([^"]*)" "([^"]*)"$')

def parse_nginx(line):
    m = PATTERN.match(line)
    if not m:
        return None
    ip, tm, method, path, proto, status, bts, ref, ua = m.groups()
    return {"ip": ip, "time": tm, "method": method, "path": path, "protocol": proto,
            "status": int(status), "bytes": None if bts == "-" else int(bts),
            "referer": ref, "user_agent": ua}
